using System;using System.IO;using System.Text;using System.Reflection;
class EncodingCheck {
 static byte[] Config(byte[] text){using(var s=new MemoryStream())using(var w=new BinaryWriter(s)){w.Write(0x45AB3EFBU);w.Write((ushort)1);w.Write((ushort)0);w.Write((ushort)12);w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)3);w.Write(Encoding.ASCII.GetBytes("MOD"));w.Write((ushort)0);w.Write((ushort)13);w.Write((ushort)0);w.Write((byte)2);w.Write((ushort)5);w.Write(Encoding.ASCII.GetBytes("Title"));w.Write((ushort)text.Length);w.Write(text);return s.ToArray();}}
 static int Main(string[] args){var a=Assembly.LoadFrom(args[0]);var type=a.GetType("EIStarter.EIRegFile");string p=Path.Combine(args[1],"fixture.reg");int count=0;foreach(var text in new[]{"Дежавю","Проклятые земли — Ёжик № 2","Dejavu","","Тест автора и описания"})foreach(var enc in new Encoding[]{new UTF8Encoding(false),Encoding.GetEncoding(1251)}){var bytes=Config(enc.GetBytes(text));File.WriteAllBytes(p,bytes);var r=Activator.CreateInstance(type);type.GetMethod("Load").Invoke(r,new object[]{p});string actual=(string)type.GetMethod("GetString").Invoke(r,new object[]{"Title","MOD","missing"});if(actual!=text){Console.WriteLine("FAIL "+enc.WebName+" expected="+text+" actual="+actual);return 1;}if(Convert.ToBase64String(File.ReadAllBytes(p))!=Convert.ToBase64String(bytes))throw new Exception("File modified");count++;}Console.WriteLine("PASS "+count+" UTF8/1251 binary config round-trips; files unchanged");return 0;}
}